// 녹음 봇이 보낸 manifest를 확인한다. 회의 ID, 파일 이름, 서버·채널 ID는 파일 경로와 Discord 요청에 들어가므로 형식이 맞는 것만 받는다.
// 틀리면 실행을 실패시켜 조용히 끝나지 않게 한다. 오류 메시지에는 값을 넣지 않는다(참석자 ID가 실행 기록에 남지 않게).
const manifest = $input.first().json.body;
const errors = [];
const isObject = (value) => value !== null && typeof value === 'object' && !Array.isArray(value);
const isMs = (value) => Number.isFinite(value) && value >= 0;

if (!isObject(manifest)) throw new Error('manifest가 JSON 객체가 아닙니다');
if (!/^\d{8}-\d{4}$/.test(manifest.meetingId ?? '')) errors.push('meetingId 형식이 다릅니다');
if (!/^\d{17,20}$/.test(manifest.guildId ?? '')) errors.push('guildId 형식이 다릅니다');
if (!/^\d{17,20}$/.test(manifest.textChannelId ?? '')) errors.push('textChannelId 형식이 다릅니다');
for (const key of ['startedAt', 'endedAt']) {
  if (typeof manifest[key] !== 'string' || Number.isNaN(Date.parse(manifest[key]))) errors.push(`${key}가 시각이 아닙니다`);
}

const participants = Array.isArray(manifest.participants) ? manifest.participants : [];
if (!Array.isArray(manifest.participants)) errors.push('participants가 배열이 아닙니다');

const segments = Array.isArray(manifest.segments) ? manifest.segments : [];
if (!Array.isArray(manifest.segments)) errors.push('segments가 배열이 아닙니다');
else if (segments.length === 0) errors.push('녹음된 발화가 없습니다');
const files = new Set();
segments.forEach((s, i) => {
  if (!/^\d{9}-\d+\.webm$/.test(s?.file ?? '')) errors.push(`segments[${i}].file 형식이 다릅니다`);
  else if (files.has(s.file)) errors.push(`segments[${i}].file이 중복됩니다`);
  else files.add(s.file);
  if (!isMs(s?.startMs) || !isMs(s?.endMs) || s.endMs < s.startMs) errors.push(`segments[${i}] 시각이 잘못됐습니다`);
});

const gaps = manifest.gaps ?? [];
if (!Array.isArray(gaps)) errors.push('gaps가 배열이 아닙니다');
else gaps.forEach((g, i) => {
  if (!isMs(g?.startMs) || (g.endMs !== undefined && (!isMs(g.endMs) || g.endMs < g.startMs))) {
    errors.push(`gaps[${i}] 시각이 잘못됐습니다`);
  }
});

if (errors.length > 0) throw new Error(`manifest를 처리할 수 없습니다: ${errors.join(', ')}`);

// 녹음 봇은 서버 멤버 정보를 못 읽으면 표시 이름 자리에 Discord ID를 넣는다.
// ID가 녹취와 OpenAI 프롬프트에 들어가지 않게 "참석자 N"으로 바꾼다.
const names = new Map();
const nameOf = (userId, displayName) => {
  if (names.has(userId)) return names.get(userId);
  const usable = typeof displayName === 'string' && displayName.trim() !== '' && !/^\d{17,20}$/.test(displayName.trim());
  const name = usable ? displayName.trim() : `참석자 ${names.size + 1}`;
  names.set(userId, name);
  return name;
};
participants.forEach((p) => nameOf(p?.userId, p?.displayName));

return [{
  json: {
    meetingId: manifest.meetingId,
    guildId: manifest.guildId,
    textChannelId: manifest.textChannelId,
    startedAt: manifest.startedAt,
    endedAt: manifest.endedAt,
    // 참석자 이름을 알려 주면 음성 인식이 이름을 덜 틀린다.
    prompt: names.size > 0 ? `참석자: ${[...new Set(names.values())].join(', ')}` : '',
    segments: segments.map((s) => ({
      file: s.file,
      startMs: s.startMs,
      endMs: s.endMs,
      speaker: nameOf(s.userId, s.displayName),
    })),
    gaps: gaps.map((g) => ({ startMs: g.startMs, endMs: g.endMs ?? null, reason: typeof g.reason === 'string' ? g.reason : '' })),
  },
}];

// 발화마다 항목 하나를 만들어 파일 읽기 노드에 넘긴다. 파일 이름은 앞 노드에서 형식을 확인했다.
const { meetingId, segments } = $('녹음 정보 확인').first().json;
return segments.map((segment) => ({
  json: { file: segment.file, path: `/recordings/${meetingId}/segments/${segment.file}` },
}));

// 파일 읽기 노드는 경로를 glob으로 찾아서, 파일이 없으면 오류 없이 항목 0개를 낸다(n8n 2.42.6에서 확인).
// 그대로 두면 워크플로가 조용히 성공으로 끝나므로 읽은 파일이 발화 목록과 하나라도 다르면 실패시킨다.
const expected = $('발화 목록').all().map((item) => item.json.file);
const files = $input.all().filter((item) => item.binary?.data);
if (files.length !== expected.length) {
  throw new Error(`발화 파일 ${expected.length}개 중 ${files.length}개만 읽었습니다. 녹음 폴더를 확인해 주세요`);
}
// 음성 인식 결과를 발화 순서로 맞추므로 읽은 순서도 같아야 한다.
const misplaced = files.findIndex((item, i) => item.binary.data.fileName !== expected[i]);
if (misplaced !== -1) throw new Error(`${misplaced + 1}번째 발화 파일이 발화 목록과 다릅니다`);
return files;

// 결정 메시지를 모을 기간을 정한다(설계 5절 D). 시작은 지난 회의록을 ClickUp에 올린 회의의 끝 시각(워크플로 static data, 9단계에서 갱신)이고,
// 없으면 이번 회의 시작 7일 전이다. 끝은 이번 회의 종료 시각이다. 기간은 "시작 초과 ~ 종료 이하"다.
// Discord 메시지 ID에는 작성 시각이 들어 있어서((ms - 2015-01-01) << 22) 기간을 메시지 ID로 바꿔 조회와 거르기에 쓴다.
const DISCORD_EPOCH = 1420070400000n;
const FIRST_RUN_LOOKBACK_MS = 7 * 24 * 60 * 60 * 1000;
// 결정 메시지 조회 노드가 이 횟수까지만 요청한다. 100개씩이라 5,000개까지 받는다(2026-10-11 사용자 결정).
const MAX_REQUESTS = 50;

const meeting = $('녹음 정보 확인').first().json;
const startedMs = Date.parse(meeting.startedAt);
const endedMs = Date.parse(meeting.endedAt);

// 저장된 시각이 이번 회의 종료보다 앞일 때만 쓴다. 없거나 시각이 아니면 처음 실행처럼 7일 전부터 본다.
const stored = $getWorkflowStaticData('global').lastMeetingEndedAt;
const storedMs = typeof stored === 'string' ? Date.parse(stored) : NaN;
const useStored = Number.isFinite(storedMs) && storedMs < endedMs;
const fromMs = useStored ? storedMs : startedMs - FIRST_RUN_LOOKBACK_MS;

// ms 밀리초에 쓰인 메시지의 ID는 idAt(ms)부터 idAt(ms + 1) - 1까지다.
const idAt = (ms) => (BigInt(ms) - DISCORD_EPOCH) << 22n;

return [{
  json: {
    guildId: meeting.guildId,
    channelId: meeting.textChannelId,
    from: new Date(fromMs).toISOString(),
    to: new Date(endedMs).toISOString(),
    source: useStored ? '지난 회의 끝 시각' : '처음 실행(회의 시작 7일 전부터)',
    // 이 ID보다 큰 메시지가 기간 시작 뒤에 쓰였다(after는 이 값을 빼고 그 뒤부터 준다).
    afterId: (idAt(fromMs + 1) - 1n).toString(),
    // 이 ID까지가 회의 종료 시각 안이다.
    endId: (idAt(endedMs + 1) - 1n).toString(),
    maxRequests: MAX_REQUESTS,
  },
}];

// 회의 채널 메시지 중 결정 메시지를 코드로 고른다(설계 5절 D, AGENTS.md 3.2). LLM은 결정 여부를 판단하지 않는다.
// 기간 안에 사람이 쓴 메시지(봇·Webhook·시스템 메시지 제외) 중 ✅ 반응이 1개 이상인 것만 고른다.
// 메시지 원문은 이 노드 출력(n8n 실행 기록, 7일 보관)에만 남긴다. 작성자 ID는 남기지 않는다.
const DISCORD_EPOCH = 1420070400000n;
// 일반 메시지(0)와 답장(19)만 사람이 쓴 글로 본다. 입장·고정 알림 같은 시스템 메시지는 뺀다.
const HUMAN_TYPES = new Set([0, 19]);

// 녹취 갈래와 따로 실행되므로(병렬 갈래) 녹취 결과를 읽지 않는다. 알림 문구는 알림 만들기 노드가 만든다.
const period = $('결정 메시지 기간').first().json;

// Discord 메시지 ID는 길이가 다를 수 있어 길이부터 비교한다.
const isAfter = (a, b) => a.length > b.length || (a.length === b.length && a > b);
const msOf = (id) => Number((BigInt(id) >> 22n) + DISCORD_EPOCH);

// 조회 노드는 메시지 하나를 항목 하나로 낸다. 받은 메시지가 없으면 alwaysOutputData로 빈 항목 하나가 온다.
// 페이지 넘김 중 오류 응답을 받으면 n8n이 오류 본문을 출력 항목으로 낼 수 있어서(n8n 2.42.6 E2E에서 확인),
// 메시지도 빈 항목도 아닌 것이 있으면 결정이 조용히 0개가 되지 않게 실패시킨다.
const isMessage = (m) => typeof m?.id === 'string' && /^\d+$/.test(m.id);
const items = $input.all().map((item) => item.json);
const unexpected = items.filter((m) => !isMessage(m) && Object.keys(m ?? {}).length > 0);
if (unexpected.length > 0) {
  throw new Error(`결정 메시지 조회 결과에 메시지가 아닌 항목이 ${unexpected.length}개 있습니다. Discord 조회가 실패했을 수 있습니다`);
}
const messages = items.filter(isMessage);

// n8n 페이지 넘김은 요청 한도에 닿으면 오류 없이 멈춘다. 한도만큼 받았는데 회의 종료 시각에 닿지 못했으면
// 더 받을 메시지가 남은 것이라 결정이 조용히 빠지지 않게 실패시킨다(2026-10-11 사용자 결정).
const newest = messages.reduce((a, m) => (isAfter(m.id, a) ? m.id : a), '0');
if (messages.length >= period.maxRequests * 100 && !isAfter(newest, period.endId)) {
  throw new Error(`회의 채널 메시지를 ${messages.length}개까지 받고도 회의 종료 시각에 닿지 못했습니다. 기간(${period.from} ~ ${period.to})을 확인해 주세요`);
}

const inWindow = (m) => isAfter(m.id, period.afterId) && !isAfter(m.id, period.endId);
const byHuman = (m) => HUMAN_TYPES.has(m.type) && !m.author?.bot && !m.webhook_id;
const checked = (m) => (m.reactions ?? []).some((r) => r?.emoji?.name === '✅' && Number(r.count) >= 1);
const picked = messages
  .filter((m) => inWindow(m) && byHuman(m) && checked(m))
  .sort((a, b) => (isAfter(a.id, b.id) ? 1 : -1));

// Message Content Intent가 꺼져 있으면 다른 사람 메시지 내용이 빈 문자열로 온다. 빈 결정이 회의록에 들어가지 않게 실패시킨다.
const blank = picked.filter((m) => String(m.content ?? '').trim() === '' && !(m.attachments ?? []).length);
if (blank.length > 0) {
  throw new Error(`✅가 달린 메시지 ${blank.length}개의 내용이 비어 있습니다. Discord 봇의 Message Content Intent가 켜져 있는지 확인해 주세요`);
}

const decisions = picked.map((m) => ({
  link: `https://discord.com/channels/${period.guildId}/${period.channelId}/${m.id}`,
  author: m.author?.global_name || m.author?.username || '알 수 없음',
  content: String(m.content ?? ''),
  attachments: (m.attachments ?? []).map((a) => a.filename),
  sentAt: new Date(msOf(m.id)).toISOString(),
}));

return [{
  json: {
    guildId: period.guildId,
    textChannelId: period.channelId,
    from: period.from,
    to: period.to,
    scanned: messages.length,
    decisionCount: decisions.length,
    decisions,
  },
}];

// 음성 인식 결과를 회의 시작 기준 시각 순 녹취로 합친다. 이 [HH:MM:SS] 문자열이 이후 단계에서 녹취 근거의 식별자가 된다.
// 녹취 원문은 이 노드 출력(n8n 실행 기록, 7일 보관)에만 남긴다. 회의 채널 알림 문구는 알림 만들기 노드가 만든다.
const meeting = $('녹음 정보 확인').first().json;
const texts = $input.all().map((item) => item.json.text);
if (texts.length !== meeting.segments.length) {
  throw new Error(`음성 인식 결과 수(${texts.length})가 발화 수(${meeting.segments.length})와 다릅니다`);
}

const pad = (n) => String(n).padStart(2, '0');
const clock = (ms) => {
  const s = Math.floor(ms / 1000);
  return `${pad(Math.floor(s / 3600))}:${pad(Math.floor(s / 60) % 60)}:${pad(s % 60)}`;
};

const lines = [];
let empty = 0;
meeting.segments.forEach((segment, i) => {
  const text = typeof texts[i] === 'string' ? texts[i].replace(/\s+/g, ' ').trim() : '';
  if (text === '') {
    empty += 1;
    return;
  }
  lines.push({ ms: segment.startMs, order: 1, text: `[${clock(segment.startMs)}] ${segment.speaker}: ${text}` });
});
// 녹음이 끊긴 구간도 시각 순으로 끼워 넣는다. 그 사이의 말은 녹음되지 않았다.
for (const gap of meeting.gaps) {
  const length = gap.endMs === null ? '회의 끝까지' : `약 ${Math.round((gap.endMs - gap.startMs) / 1000)}초`;
  const reason = gap.reason ? `, ${gap.reason}` : '';
  lines.push({ ms: gap.startMs, order: 0, text: `[${clock(gap.startMs)}] (녹음 끊김 ${length}${reason})` });
}
lines.sort((a, b) => a.ms - b.ms || a.order - b.order);

const segmentCount = meeting.segments.length;
return [{
  json: {
    meetingId: meeting.meetingId,
    guildId: meeting.guildId,
    textChannelId: meeting.textChannelId,
    transcript: lines.map((line) => line.text).join('\n'),
    segmentCount,
    emptyCount: empty,
  },
}];

// 두 갈래(결정 메시지, 녹취)가 모두 끝난 뒤 회의 채널 알림 문구를 만든다.
// Discord 노드에는 멘션을 끄는 옵션이 없어서 녹취·결정 메시지 원문 같은 사람이 쓴 글은 넣지 않고 회의 ID와 숫자만 쓴다.
const meeting = $('녹음 정보 확인').first().json;
const transcript = $('녹취 만들기').first().json;
const picked = $('결정 메시지 고르기').first().json;
return [{
  json: {
    guildId: meeting.guildId,
    textChannelId: meeting.textChannelId,
    notice: `회의 ${meeting.meetingId} 녹취 완료, 발화 ${transcript.segmentCount}개, 결정 메시지 ${picked.decisionCount}개`,
  },
}];
